parameters.text:
={{ (() => {
  const rows = $input.all();
  const count = (names) => {
    const row = rows.find(i => names.includes(String(i.json.materia ?? '').trim().toLowerCase()));
    return Number(row?.json.count_materia ?? row?.json.count ?? 0);
  };
  const math = count(['matematica','matemática','matematicas','matemáticas']);
  const prog = count(['programacion','programación']);
  const chem = count(['quimica','química']);
  const total = rows.reduce((sum, i) => sum + Number(i.json.count_materia ?? i.json.count ?? 0), 0);
  return `Resumen de Tutorías por Materia

Matemáticas: ${math}
Programación: ${prog}
Química: ${chem}
TOTAL SEMANA: ${total}`;
})() }}
